"""Write src/reactive/ReflexTables.sol from the tables in ml/features.py.

Run after any change to DECAY or SIGMOID:  .venv/bin/python ml/gen_tables.py
"""
import os

import features as F

TEMPLATE = """// SPDX-License-Identifier: MIT
pragma solidity ^0.8.29;

/// @title ReflexTables
/// @notice Lookup tables for the fixed-point pipeline. Generated by ml/gen_tables.py; do not edit by hand.
library ReflexTables {{
    /// @dev 2^(-k/32) in Q16 for k = 0..31, 4 bytes per entry, big endian.
    bytes internal constant DECAY = hex"{decay}";

    /// @dev 10000 * sigmoid(x) for x = -8.0 .. 8.0 in steps of 0.5, 2 bytes per entry, big endian.
    bytes internal constant SIGMOID = hex"{sigmoid}";
}}
"""


def main():
    decay = "".join(f"{v:08x}" for v in F.DECAY)
    sigmoid = "".join(f"{v:04x}" for v in F.SIGMOID)
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "src", "reactive", "ReflexTables.sol")
    os.makedirs(os.path.dirname(out), exist_ok=True)
    with open(out, "w") as fh:
        fh.write(TEMPLATE.format(decay=decay, sigmoid=sigmoid))


if __name__ == "__main__":
    main()
